  const state = {loaded:false, busy:false, assetsStale:false, pendingResultAssetId:"", currentProjectId:"", projects:[], assets:[], tasks:[], textConversations:[], selectedDoubaoAssetIds:new Set(), resourceMode:"assets", resourceProjectRailOpen:true, projectStatus:"active", assetStatus:"active", assetType:"all", assetProject:"all", assetSearch:""};
  let refreshTimer=null,modalSequence=0;
  const focusableSelector='button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
