      const validIds=new Set(state.assets.filter(asset=>!asset.deletedAt&&!asset.archivedAt&&doubaoVideoTask(asset)).map(asset=>asset.id));for(const id of state.selectedDoubaoAssetIds)if(!validIds.has(id))state.selectedDoubaoAssetIds.delete(id);
